"use strict";(globalThis.webpackChunkopnsense_documentation||=[]).push([[367],{9899(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"margin-notes-beside-the-handbook","metadata":{"permalink":"/TW4TECH-Documentation-Deliverables/blog/margin-notes-beside-the-handbook","source":"@site/blog/2026-09-30-margin.mdx","title":"I stopped rewriting the official handbook","description":"The handbook at docs.opnsense.org is already the book. My mistake was trying to compete with it. What I needed was a margin: the three facts that stall a first boot, written where I can see them without searching.","date":"2026-09-30T00:00:00.000Z","tags":[{"inline":false,"label":"OPNsense","permalink":"/TW4TECH-Documentation-Deliverables/blog/tags/opnsense","description":"Notes about the firewall lab"},{"inline":false,"label":"Lab","permalink":"/TW4TECH-Documentation-Deliverables/blog/tags/lab","description":"Virtual machine and first login"}],"readingTime":0.79,"hasTruncateMarker":true,"authors":[{"name":"Comfort Agwu","title":"Technical writer","url":"https://github.com/ComfortAgwu89","imageURL":"https://github.com/ComfortAgwu89.png","key":"comfort","page":null}],"frontMatter":{"slug":"margin-notes-beside-the-handbook","title":"I stopped rewriting the official handbook","authors":["comfort"],"tags":["opnsense","lab"]},"unlisted":false},"content":"The handbook at [docs.opnsense.org](https://docs.opnsense.org/) is already the book. My mistake was trying to compete with it. What I needed was a margin: the three facts that stall a first boot, written where I can see them without searching.\\n\\n{/* truncate */}\\n\\n## The margin\\n\\nThe live installer is `installer` / `opnsense`. The GUI is `root`, on `https://192.168.1.1/`, until you move the LAN. There is no official Docker image. The download is an ISO from [opnsense.org/download](https://opnsense.org/download/), and virtual machines are described at [docs.opnsense.org/manual/virtuals.html](https://docs.opnsense.org/manual/virtuals.html).\\n\\n## The door\\n\\nOnce the page loads, scripts use the same house. HTTP Basic, key then secret, path `/api/<module>/<controller>/<command>/`. The how-to I keep pinned is [Use the API](https://docs.opnsense.org/development/how-tos/api.html). The code is [github.com/opnsense/core](https://github.com/opnsense/core).\\n\\nI do not need a second product in this repository to have something to curl. The appliance is the product."}]}}')}}]);